283	    /**
284	     * Counts the existing owners that already share the given firstName and lastName, compared
285	     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
286	     * the owners that pre-existed this create.
287	     *
288	     * @param firstName the new owner's first name
289	     * @param lastName  the new owner's last name
290	     * @return the number of existing namesakes
291	     */
292	    private int countNamesakes(String firstName, String lastName) {
