299	    /**
300	     * Flags an owner as a possible (soft) duplicate. Although it is not a hard duplicate (its whole
301	     * {@link #identityKey(Owner) identityKey} is unique, so the create was not rejected), it may
302	     * still resemble an existing owner: when it shares an existing owner's lastName (compared
303	     * case-insensitively) and postcode while carrying a different telephone, the owner is flagged
304	     * with {@code possibleDuplicate=true} and {@code possibleDuplicateOf} set to that existing
305	     * owner's id. When no such owner exists the flag is set to {@code false} and no match id is
306	     * recorded. An owner with no postcode can never soft-match and is always {@code false}.
307	     *
308	     * <p>A declared household member (created with {@code sharesHousehold=true}) is never a suspected
309	     * duplicate: its match with an existing household member is a deliberate, declared one, so it is
310	     * always flagged {@code false}.
311	     *
312	     * @param owner           the owner being created, with its normalized telephone already applied
313	     * @param sharesHousehold whether the request declared it shares a household; a declared member is
314	     *                        never flagged as a possible duplicate
315	     */
316	    private void flagPossibleDuplicate(Owner owner, boolean sharesHousehold) {
317	        Owner match = sharesHousehold ? null : findPossibleDuplicate(owner);
318	        if (match != null) {
319	            owner.setPossibleDuplicate(true);
320	            owner.setPossibleDuplicateOf(match.getId());
321	        } else {
322	            owner.setPossibleDuplicate(false);
323	            owner.setPossibleDuplicateOf(null);
324	        }
325	    }
