491	    /**
492	     * Derives an owner's region from its city using the fixed city-to-region table (Sydney->NSW,
493	     * Melbourne->VIC, Brisbane->QLD), returning {@code null} when the city is not in the table.
494	     *
495	     * @param city the owner's city
496	     * @return the region code, or {@code null} when the city has no known region
497	     */
498	    private String region(String city) {
499	        if (city == null) {
500	            return null;
501	        }
502	        return switch (city) {
503	            case "Sydney" -> "NSW";
504	            case "Melbourne" -> "VIC";
505	            case "Brisbane" -> "QLD";
506	            default -> null;
507	        };
508	    }
