616	    /**
617	     * Derives an owner's {@code identityKey}: {@code normalizedTelephone + '|' + (email or empty) +
618	     * '|' + householdId}. A {@code null} email or householdId contributes an empty segment. Every
619	     * duplicate decision is made by comparing whole identityKeys.
620	     *
621	     * @param owner the owner whose identityKey to derive
622	     * @return the derived identityKey
623	     */
624	    private String identityKey(Owner owner) {
625	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
626	        String email = owner.getEmail() == null ? "" : owner.getEmail();
627	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
628	        return telephone + "|" + email + "|" + householdId;
629	    }
